import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    degree = [0] * n
    graph = [[] for _ in range(n)]
    for i in range(n):
        degree[i] = a[i]

    queue = deque([i for i in range(n) if degree[i] == 0])

    order = []
    while queue:
        u = queue.popleft()
        order.append(u)
        for v in graph[u]:
            degree[v] -= 1
            if degree[v] == 0:
                queue.append(v)

    if len(order) != n:
        print("Impossible")
        return

    used = [False] * n
    teams = []
    for i in order:
        if not used[i]:
            current_team = []
            for j in range(n):
                if a[j] == 2 and not used[j]:
                    current_team.append(j)
                    used[j] = True
                    a[j] = 0
            if len(current_team) == 3:
                teams.append(current_team)
                for student in current_team:
                    for k in range(n):
                        if a[k] > 0 and student in graph[k]:
                            graph[k].remove(student)
                            a[k] -= 1
            else:
                break

    if len(teams) * 3 + sum(a) != n:
        print("Impossible")
        return

    result_order = []
    used_in_teams = set()
    for team in teams:
        for student in team:
            used_in_teams.add(student)
            result_order.append(student + 1)

    for i in range(n):
        if not used_in_teams and a[i] == 0:
            result_order.append(i + 1)

    if len(result_order) != n:
        print("Impossible")
    else:
        print("Possible")
        print(" ".join(map(str, result_order)))

if __name__ == "__main__":
    main()
